{
  "missing_information": [
    {
      "category": "Trigger & Timing",
      "gap": "It is unclear what initiates the preparation process — whether it is a fixed schedule, a spontaneous decision, or an external prompt — and how far in advance preparation begins.",
      "why_it_matters": "The trigger and lead time determine whether automation can proactively start checklists or reminders, or must wait for a manual signal."
    },
    {
      "category": "Participants & Coordination",
      "gap": "The identity and number of people being coordinated with ('whoever is coming') is unspecified, as is how coordination currently happens (e.g., messaging, phone call, in-person).",
      "why_it_matters": "The coordination channel and participant variability affect whether automated notifications or confirmations can be sent and to whom."
    },
    {
      "category": "Items & Packing Logic",
      "gap": "There is no detail on what 'getting things together' involves — which items are gathered, whether the list varies by destination or activity type, and who is responsible for each item.",
      "why_it_matters": "A defined, possibly conditional item list is essential for building a checklist or automated packing assistant."
    },
    {
      "category": "Decision Points",
      "gap": "There are no described decision points or branching conditions, such as what happens if a participant cancels, if an item is missing, or if the outing is postponed.",
      "why_it_matters": "Exception paths must be mapped to assess process robustness and determine where automation needs fallback logic."
    },
    {
      "category": "Return & Storage Process",
      "gap": "'Putting things away for next time' is vague — it is unclear which items are stored, where they go, whether any cleaning or restocking occurs, and how completion is confirmed.",
      "why_it_matters": "The post-outing steps need to be discrete and sequenced to evaluate automation potential and ensure readiness for the next outing."
    },
    {
      "category": "Tools & Current Systems",
      "gap": "No information is given about any tools, apps, or systems currently used to support any part of this workflow (e.g., shared calendars, reminder apps, shopping lists).",
      "why_it_matters": "Existing tools indicate integration points and the baseline level of digitisation, which shapes what automation is feasible without major new infrastructure."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What typically triggers the start of your preparation — for example, a planned date on a calendar, a spontaneous same-day decision, or something else — and roughly how much time before leaving do you begin getting things ready?",
      "targets": ["Trigger & Timing"]
    },
    {
      "id": "Q2",
      "question": "Who are the people you coordinate with before the outing, and how do you currently communicate with them to confirm plans or share information?",
      "targets": ["Participants & Coordination"]
    },
    {
      "id": "Q3",
      "question": "Can you walk me through the specific items or categories of items you gather before leaving, and does this list change depending on the type of outing or destination?",
      "targets": ["Items & Packing Logic"]
    },
    {
      "id": "Q4",
      "question": "What do you do if something goes wrong during preparation — for instance, if a key item is missing or a participant can no longer come?",
      "targets": ["Decision Points"]
    },
    {
      "id": "Q5",
      "question": "When you put things away after returning, what specific steps are involved — for example, cleaning, restocking, or storing items in particular places — and how do you know when everything is properly done?",
      "targets": ["Return & Storage Process"]
    },
    {
      "id": "Q6",
      "question": "Are there any apps, tools, or systems you already use to support any part of this process, such as a shared calendar, a packing checklist app, or a messaging platform?",
      "targets": ["Tools & Current Systems"]
    }
  ]
}
